// Cubed
// For the #WCCChallenge << Three Colors >> (join the discord! https://discord.gg/S8c7qcjw2b)

var cw, ch
var hexSize, h, w, hexWeight
var palettes = [
  ["#330f0a", "#394f49", "#efdd8d"],
  ["#f6f7eb", "#c63d24", "#3a4145"],
  ["#33888a", "#57c1ac", "#233e3c"],
  ["#e7cb2b", "#1a8e1c", "#274e82"],
  ['#cc1071', '#8bee20', '#235a8f'],
  ["#717574", "#DBC665", "#603D69"],
  ["#ECED8C", "#591258", "#238A8C"],
  ["#7a6894", "#4e88b0", "#e3bfa6"],
]
var palette, paletteIndex
var delayFrames = 20
var cycleFrames = 100
var outerPoints, innerPoints, holePoints, innerHolePoints
var maxDist

function setup() {
  cw = windowWidth
  ch = windowHeight
  hexSize = random(80, 120)
  maxDist = dist(0, 0, cw / 2, ch / 2)
  createCanvas(cw, ch)
  texture = granulate(100)

  h = hexSize * sin(PI / 3) * 2
  w = (hexSize * 3) / 2
  if (random() < 0.7) {
    hexWeight = hexSize / random(2.5, 4)
  } else {
    hexWeight = hexSize / random(4, 8)
  }

  paletteIndex = floor(random(palettes.length))
  palette = palettes[paletteIndex]

  outerPoints = getPoints(hexSize)
  innerPoints = getPoints(hexSize - hexWeight)
  holePoints = getPoints(hexSize - hexWeight * 2)
  innerHolePoints = getPoints(hexWeight)
  pixelDensity(1)
}

var fc = -1
var paused = false
function draw() {
  if (!paused) { fc++ }
  if (paused) {
    if (keyIsDown(LEFT_ARROW)) {
      fc = max(fc - 1, 0)
    } else if (keyIsDown(RIGHT_ARROW)) {
      fc++
    }
  }

  let index = floor(fc / cycleFrames) % 3
  if (index < 0) { index = 3 + index }
  background(palette[index])
  let sx = ceil(cw / (3 * hexSize)) + 2
  let sy = ceil(ch / (4 * hexSize)) + 2

  push()
  translate(cw / 2, ch / 2)
  for (let x = -sx; x <= sx; x++) {
    for (let y = -sy; y <= sy; y++) {
      let px = x * w
      let py = y * h
      if (x % 2) { py += h / 2 }
      push()
      translate(px, py)
      drawBgHex(hexSize, px, py)
      pop()
    }
  }
  for (let x = -sx; x <= sx; x++) {
    for (let y = -sy; y <= sy; y++) {
      var px = x * w
      var py = y * h
      if (x % 2) { py += h / 2 }
      push()
      translate(px, py)
      drawFgHex(hexSize, px, py)
      pop()
    }
  }
  pop()

  blendModeimage(texture, 0, 0)
  blendMode(BLEND)
}

var getPoints = (hexSize) => {
  let points = []
  for (let i = 0; i < 6; i++) {
    let angle = (PI / 3) * i
    var px = hexSize * cos(angle)
    var py = hexSize * sin(angle)
    points.push([px, py])
  }
  return points
}

var getRotation = (x, y, totalAngle) => {
  let activeFrames = cycleFrames - delayFrames
  let frame = fc % cycleFrames
  let factor = map(dist(x, y, 0, 0), 0, maxDist, 1, 0, true)
  let startFrame = floor(delayFrames * factor)
  if (frame < startFrame) {
    return 0
  } else if (frame > startFrame + activeFrames) {
    return totalAngle
  }
  let eased = easing(map(frame, startFrame, startFrame + activeFrames, 0, 1))
  return eased * totalAngle
}

var drawBgHex = (hexSize, x, y) => {
  let colors = [...palette]
  let invert = floor(fc / cycleFrames) % 2 === 1
  noStroke()
  if (invert) {
    translate(hexSize, 0)
    scale(-1, -1)
  }
  for (let i = 0; i < 3; i++) {
    push()
    let startRotation = (floor(fc / cycleFrames) % 3) * ((2 * PI) / 3)
    let rotation = getRotation(x, y, (2 * PI) / 3)
    rotate(startRotation + rotation)
    rotate((PI / 3) * 2 * i)
    fill(colors[(i + 2 - !!invert) % 3])
    triangle(0, 0, ...outerPoints[0], ...outerPoints[1])
    fill(colors[(i + 1 + !!invert) % 3])
    triangle(0, 0, ...outerPoints[0], ...outerPoints[5])
    pop()
  }
}

var _colorOrders = [[0, 1, 2], [1, 0, 2], [2, 0, 1], [2, 1, 0], [1, 2, 0], [0, 2, 1]]
var drawFgHex = (hexSize, x, y) => {
  var colors = [...palette]
  let dx = -hexWeight / 2
  let dy = hexWeight * sin(PI / 3)
  var invert = floor(fc / cycleFrames) % 2 === 1
  if (invert) {
    translate(hexSize, 0)
    scale(-1, 1)
  }

  let cycle = floor(fc / cycleFrames) % 6
  colors = _colorOrders[cycle].map((i) => colors[i])

  var startRotation = (floor(fc / cycleFrames) % 3) * ((2 * PI) / 3)
  var rotation = getRotation(x, y, (2 * PI) / 3)
  rotate(startRotation + rotation)
  strokeWeight(1.5)
  stroke(0)

  for (let i = 0; i < 3; i++) {
    push()
    rotate((PI / 3) * 2 * i)
    fill(colors[i])
    beginShape()
    vertex(...outerPoints[0])
    vertex(...outerPoints[1])
    vertex(0, 0)
    vertex(...outerPoints[5])
    beginContour()
    vertex(...innerPoints[0])
    vertex(innerPoints[5][0] - dx, innerPoints[5][1] + dy)
    vertex(-2 * dx, 0)
    vertex(innerPoints[1][0] - dx, innerPoints[1][1] - dy)
    endContour()
    endShapepop()
  }
}

function keyPressed() {
  if (keyCode === 32) { // Space bar
    if (palettes.length > 1) {
      let nc = floor(random(palettes.length))
      let _wG_1 = 0; while ((nc === paletteIndex) && ++_wG_1 < 20000) {
        nc = floor(random(palettes.length))
      }
      paletteIndex = nc
      palette = palettes[paletteIndex]
    }
  }
  if (keyCode === 82) { // R
    fc = 0
  }
  if (keyCode === 80) { // P
    paused = !paused
  }
}

var easing = (x) => {
  return x * x * x
}

var texture
function granulate(gA) {
	let s = 2 * maxDist
  let gc = createGraphics(s, s)
  gc?.loadPixels?.()
  let d = gc.pixelDensity()
  let halfImage = 4 * (s * d) * (s * d)
  for (let ii = 0; ii < halfImage; ii += 4) {
    grainAmount = random(-gA, gA)
    gc.pixels[ii] = gc.pixels[ii] + grainAmount
    gc.pixels[ii + 1] = gc.pixels[ii + 1] + grainAmount
    gc.pixels[ii + 2] = gc.pixels[ii + 2] + grainAmount
    gc.pixels[ii + 3] = gc.pixels[ii + 3] + gA
  }
  gc.updatePixels()
  return gc
}
